/// The drawer a row of the table opens, filled for one order: over the table,
/// 60% of the screen wide.
pub fn order_drawer(view: &OrderView, today: NaiveDate, parts: Parts<'_>) -> Sheet {
    let order = &view.order;
    Sheet::new(DRAWER, format!("Order {}", order.number))
        .width(SheetWidth::Xl)
        .description(format!(
            "{} for {} in {}",
            units(order.items),
            order.customer,
            place_of(&order.city, &order.state, &order.country)
        ))
        .body((order_detail(view, 3, today, true, parts), dialogs(view)))
}

/// Everything about one order: the summary and the actions, four facts, the
/// items, the steps, the customer's other orders and the notes. `level` is the
/// level of the headings inside, under the drawer's title or the page's.
pub fn order_detail(
    view: &OrderView,
    level: u8,
    today: NaiveDate,
    open_as_page: bool,
    parts: Parts<'_>,
) -> Stack {
    let order = &view.order;
    let id = order.id;
    let history: Node = match parts {
        Parts::Lazy => Region::new(STEPS)
            .src(format!("/orders/{id}/steps"))
            .lazy()
            .into(),
        Parts::Inline { history, .. } => steps(order, history, level + 1).into(),
    };
    let others: Node = match parts {
        Parts::Lazy => Region::new(OTHERS)
            .src(format!("/orders/{id}/others"))
            .lazy()
            .into(),
        Parts::Inline { others, .. } => other_orders(others, today),
    };
    Stack::gap(4).children((
        summary(view, today),
        toolbar(view, open_as_page),
        facts(view),
        lines_card(view, level),
        Card::titled("Progress")
            .heading(level)
            .description(match Fulfilment::parse(&order.fulfilment) {
                _ if Status::parse(&order.status) == Status::Cancelled => {
                    "Cancelled before it shipped".to_owned()
                }
                Fulfilment::Delivered => "Delivered".to_owned(),
                step => format!("{} so far", step.label()),
            })
            .body(history),
        Card::titled(format!("More from {}", order.customer))
            .heading(level)
            .description(format!(
                "{} {} in all",
                thousands(i64::try_from(view.orders).unwrap_or(0)),
                if view.orders == 1 { "order" } else { "orders" }
            ))
            .body(others),
        notes(view, level),
    ))
}

/// Who bought it, how they paid, and where it goes.
fn facts(view: &OrderView) -> FactGrid {
    let order = &view.order;
    let house = warehouse(&order.warehouse);
    let customer = FactCard::new("Customer", order.customer.clone())
        .icon(icons::USER)
        .tone(Tone::Info)
        .detail(order.email.clone())
        .detail(crate::data::phone_text(&view.phone))
        .detail(match view.since {
            Some(day) => format!(
                "{} {} since {}",
                thousands(i64::try_from(view.orders).unwrap_or(0)),
                if view.orders == 1 { "order" } else { "orders" },
                day.format("%b %Y")
            ),
            None => "First order".to_owned(),
        });
    let paid = Payment::parse(&order.payment);
    let payment = FactCard::new("Payment", paid_with(order))
        .icon(method_icon(&order.method))
        .tone(paid.tone())
        .detail(match paid {
            Payment::Pending if order.method == "cod" => {
                format!("{} to collect on delivery", money(order.total))
            }
            Payment::Pending => format!("{} expected", money(order.total)),
            _ => format!("{} paid", money(order.total)),
        })
        .detail(match paid {
            Payment::Refunded => "Refunded in full".to_owned(),
            Payment::PartiallyRefunded => format!("{} refunded", money(order.refunded)),
            Payment::Pending => "Nothing paid yet".to_owned(),
            Payment::Paid => "Nothing refunded".to_owned(),
        });
    let from = FactCard::new("Ships from", city("IN", house.city))
        .icon(icons::WAREHOUSE)
        .detail(warehouse_line(house));
    let step = Fulfilment::parse(&order.fulfilment);
    let to = FactCard::new("Ships to", city(&order.country, &order.city))
        .icon(icons::MAP_PIN)
        .tone(Tone::named("violet"))
        .detail(if order.pin.is_empty() {
            country_name(&order.country).to_owned()
        } else {
            format!(
                "{}, PIN {}",
                crate::data::state_name(&order.state),
                order.pin
            )
        })
        .detail(if order.tracking.is_empty() {
            match step {
                _ if Status::parse(&order.status) == Status::Cancelled => "Not shipping".to_owned(),
                _ => format!("{}, once packed", house.carrier),
            }
        } else {
            format!("{} · {}", house.carrier, order.tracking)
        });
    FactGrid::new().cols(2).cards([customer, payment, from, to])
}

/// The live feed: newest first, in a region that a server-sent event stream
/// keeps current. An event only nudges it: the feed asks its own server for the
/// rows that came after the newest it has.
pub fn activity_feed(entries: &[FeedEntry], total: u64) -> Region {
    let newest = entries
        .first()
        .map_or_else(Cursor::default, |entry| Cursor::of(&entry.event));
    ActivityFeed::new("activity", "Order activity")
        .heading(2)
        .live()
        .summary(format!(
            "{} events in the last 24 hours",
            thousands(i64::try_from(total).unwrap_or(0))
        ))
        .time_zone(ZONE, OFFSET)
        .height(FeedHeight::Lg)
        .items(entries.iter().map(activity_item))
        .empty(Empty::new("Quiet so far").description("New orders show up here as they come in."))
        .in_region(
            "activity-region",
            "/fragments/activity",
            "/events",
            newest.to_string(),
        )
        .live_event("activity")
}

/// One row: who did what to which order or product, in the tone of what it was,
/// with the facts that matter under it.
pub fn activity_item(entry: &FeedEntry) -> ActivityItem {
    let event = &entry.event;
    let Some(kind) = Kind::parse(&event.kind) else {
        return ActivityItem::new("The shop", "changed").at(event.at);
    };
    let order = format!("/orders/{}", event.order_id);
    let to = || {
        Meta::flag(
            Flag::country(&entry.country).size(FlagSize::Xs),
            place_of(&entry.city, &entry.state, &entry.country),
        )
    };
    let house = warehouse(&entry.warehouse);
    let item = match kind {
        Kind::Placed => ActivityItem::new(event.actor.clone(), "placed")
            .object(entry.number.clone())
            .meta(Meta::icon(
                icons::SHOPPING_BAG,
                format!("{} · {}", units(entry.items), money(event.amount)),
            ))
            .meta(to())
            .href(order),
        Kind::Paid => ActivityItem::new(
            event.actor.clone(),
            if entry.method == "cod" {
                "took the cash for"
            } else {
                "paid for"
            },
        )
        .object(entry.number.clone())
        .meta(Meta::icon(
            method_icon(&entry.method),
            format!("{} · {}", money(event.amount), method_words(&entry.method)),
        ))
        .href(order),
        Kind::Packed => ActivityItem::new(format!("{} warehouse", house.city), "packed")
            .object(entry.number.clone())
            .meta(Meta::icon(icons::PACKAGE, units(event.amount)))
            .href(order),
        Kind::Shipped => ActivityItem::new(format!("{} warehouse", house.city), "shipped")
            .object(entry.number.clone())
            .meta(Meta::icon(icons::TRUCK, event.detail.clone()).ltr())
            .meta(to())
            .href(order),
        Kind::Delivered => ActivityItem::new(event.actor.clone(), "delivered")
            .object(entry.number.clone())
            .meta(to())
            .href(order),
        Kind::Refunded => ActivityItem::new(
            event.actor.clone(),
            format!("refunded {} on", money(event.amount)),
        )
        .object(entry.number.clone())
        .meta(Meta::new(event.detail.clone()))
        .href(order),
        Kind::Cancelled => ActivityItem::new(event.actor.clone(), "cancelled")
            .object(entry.number.clone())
            .meta(Meta::new(event.detail.clone()))
            .href(order),
        Kind::Resent => ActivityItem::new(event.actor.clone(), "sent again the confirmation of")
            .object(entry.number.clone())
            .href(order),
        Kind::LowStock => ActivityItem::new(
            event.actor.clone(),
            if event.amount <= 0 {
                "ran out"
            } else {
                "is running low"
            },
        )
        .tag(format!("{} left", thousands(event.amount)))
        .href("/inventory?f.level=low&f.level=out"),
        Kind::Restocked => ActivityItem::new(
            event.actor.clone(),
            format!("added {} of", units(event.amount)),
        )
        .object(event.detail.clone())
        .href("/inventory"),
    };
    item.tone(kind.tone())
        .icon(kind.icon())
        .at(event.at)
        .id(format!("event-{}", event.id))
}

/// The three panes and their rules, with nothing in them: the page draws it, and a
/// save is read against it.
pub fn layout() -> SplitPane {
    SplitPane::new(SPLIT)
        .height(SplitHeight::Screen)
        .stack_below(SplitWidth::Md)
        .save_to("/inbox/panes")
        .pane(
            Pane::new("conversations", "Conversations")
                .size(30)
                .min(22)
                .max(45),
        )
        .pane(Pane::fill("thread", "Conversation").min(30))
        .pane(
            Pane::new("customer", "Customer")
                .size(26)
                .min(18)
                .max(40)
                .collapsible()
                .collapse_below(SplitWidth::Lg),
        )
}

/// The panes, drawn with the agent's sizes.
pub fn inbox_split(page: &Inbox<'_>, sizes: Option<&SplitSizes>) -> SplitPane {
    let path = page_path(page.open);
    let stream = stream_url(page.open);
    let mut split = layout();
    if let Some(sizes) = sizes {
        split = split.sizes(sizes);
    }
    let split = split.current(page.pane).pane_with("conversations", |pane| {
        pane.header(list_header(page.filters, &path, page.keys))
            .body(list_body(page, &stream))
    });
    match page.open {
        Some(thread) => {
            let open = Open {
                conversation: &thread.conversation,
                customer: &thread.customer,
                assignee: thread.assignee.clone(),
                filters: page.filters,
                now: page.now,
                today: page.today,
                neighbours: thread.neighbours,
                keys: page.keys,
            };
            let back = page.filters.href(&path);
            let window = Window {
                messages: &thread.messages,
                files: &thread.files,
                older: thread.older,
                newer: thread.newer,
            };
            split
                .pane_with("thread", |pane| {
                    pane.header(head_region(&open))
                        .body(thread_lazy(
                            &thread.conversation,
                            &window,
                            &stream,
                            page.now,
                            page.me,
                        ))
                        .from_end()
                        .body_label("Messages")
                        .footer(composer(
                            &thread.conversation,
                            page.draft,
                            page.kind,
                            page.error,
                            page.keys,
                        ))
                })
                .pane_with("customer", |pane| {
                    pane.header(customer_head(&thread.customer, &back)).body(customer_region(
                        thread.conversation.id,
                        thread.customer.id,
                        page.filters,
                        page.customer,
                        page.now,
                    ))
                })
        }
        None => split
            .pane_with("thread", |pane| {
                let first = page.list.rows.first().map(|row| {
                    // j opens the first; on a conversation's page, j and k are its neighbours.
                    let button = Button::outline("Open the first")
                        .href(page.filters.href(&format!("/inbox/{}", row.conversation.id)));
                    if page.keys { button.hotkey("j") } else { button }
                });
                let empty = Empty::new("Choose a conversation")
                    .icon(icons::MESSAGES_SQUARE)
                    .description(if page.keys {
                        "Pick one from the list, or press j to open the first. Press ? for every key."
                    } else {
                        "Pick one from the list."
                    });
                pane.body(match first {
                    Some(button) => empty.actions(button),
                    None => empty,
                })
            })
            .pane_with("customer", |pane| {
                pane.body(
                    Empty::new("No customer yet")
                        .icon(icons::USER_ROUND)
                        .description("Their plan, history and tags show here with a conversation."),
                )
            }),
    }
}

/// The list: lazy, live, and kept as the agent left it while they open conversations.
pub fn list_lazy(
    page: &ListPage<'_>,
    filters: &Filters,
    open: Option<i64>,
    now: i64,
    stream: &str,
) -> LazyList {
    let path = match open {
        Some(id) => format!("/inbox/{id}"),
        None => "/inbox".to_owned(),
    };
    let window = |param: &str, cursor: String| {
        let base = filters.href(&path);
        let sep = if base.contains('?') { '&' } else { '?' };
        format!("{base}{sep}{param}={}", encode(&cursor))
    };
    let mut list = LazyList::new(LIST, "Conversations", rows_src(filters))
        .view(filters.query())
        .items(
            page.rows
                .iter()
                .map(|row| conversation_item(row, filters, open, now, None)),
        )
        .since(page.since.clone())
        .live_from(stream.to_owned(), Some("conversations"), LazyEnd::Start)
        .max(300)
        .labels(LazyLabels {
            start: "Show newer conversations".to_owned(),
            end: "Show more conversations".to_owned(),
            loaded: "{n} more conversations".to_owned(),
            ..LazyLabels::default()
        })
        .empty(if filters.narrowed() {
            Empty::new("Nothing matches")
                .icon(icons::SEARCH)
                .description("No conversation in this view matches the search and filters.")
                .actions(
                    Button::outline("Clear the filters")
                        .href(Filters::with_view(filters.view).href("/inbox")),
                )
        } else {
            Empty::new("All caught up").icon(icons::INBOX).description(
                "Nothing is waiting in this view. New conversations show up here as they arrive.",
            )
        });
    if let Some(id) = open {
        list = list.current(id.to_string());
    }
    if page.more_after
        && let Some(last) = page.rows.last()
    {
        list = list.more_after(window("rows_after", last.conversation.cursor()));
    }
    if page.more_before
        && let Some(first) = page.rows.first()
    {
        list = list.more_before(window("rows_before", first.conversation.cursor()));
    }
    list
}

/// The messages, oldest first: a lazy list that starts at the newest. New ones arrive at
/// the end, live, and are read out briefly; the server hears when they were seen.
pub fn thread_lazy(
    conversation: &Conversation,
    window: &Window<'_>,
    stream: &str,
    now: i64,
    me: i64,
) -> LazyList {
    let id = conversation.id;
    let mut list = LazyList::new(MESSAGES, "Messages", format!("/inbox/{id}/messages"))
        .order(LazyOrder::Ascending)
        .view(format!("conversation-{id}"))
        .gap(4)
        .items(
            window
                .messages
                .iter()
                .map(|item| message_item(item, window.files, now, me)),
        )
        .since(window.messages.last().map_or(0, |last| last.id).to_string())
        .live_from(stream.to_owned(), Some("thread"), LazyEnd::End)
        .announce_new("{n} new messages", "A new message")
        .seen_by(format!("/inbox/{id}/seen"))
        .max(400)
        .labels(LazyLabels {
            start: "Show earlier messages".to_owned(),
            end: "Show newer messages".to_owned(),
            loaded: "{n} more messages".to_owned(),
            ..LazyLabels::default()
        });
    if window.older
        && let Some(first) = window.messages.first()
    {
        list = list.more_before(format!("/inbox/{id}?older={}", message_cursor(first.id)));
    }
    if window.newer
        && let Some(last) = window.messages.last()
    {
        list = list.more_after(format!("/inbox/{id}?newer={}", message_cursor(last.id)));
    }
    list
}

/// A page of the list: the rows, whether more come after them, and whether more come
/// before them. A cursor that doesn't read is the first page.
pub async fn list_page(
    uow: &(impl Executor + ?Sized),
    filters: &Filters,
    me: i64,
    ask: &LazyAsk,
) -> Result<(Vec<ListRow>, bool, bool)> {
    let query = in_view(filters, me);
    let cursor = |text: &str| read_cursor(text);
    let (found, more_after, more_before) = match ask {
        LazyAsk::After(text) if cursor(text).is_some() => {
            let (at, id) = cursor(text).unwrap_or_default();
            let mut found = inner(
                query
                    .where_(after(at, id))
                    .order_by_desc("last_at")
                    .order_by_desc("id")
                    .limit(PAGE + 1)
                    .get(uow)
                    .await?,
            );
            let more = found.len() as u64 > PAGE;
            found.truncate(PAGE as usize);
            (found, more, true)
        }
        LazyAsk::Before(text) if cursor(text).is_some() => {
            let (at, id) = cursor(text).unwrap_or_default();
            let mut found = inner(
                query
                    .where_(before(at, id))
                    .order_by("last_at")
                    .order_by("id")
                    .limit(PAGE + 1)
                    .get(uow)
                    .await?,
            );
            let more = found.len() as u64 > PAGE;
            found.truncate(PAGE as usize);
            found.reverse();
            (found, true, more)
        }
        _ => {
            let mut found = inner(
                query
                    .order_by_desc("last_at")
                    .order_by_desc("id")
                    .limit(PAGE + 1)
                    .get(uow)
                    .await?,
            );
            let more = found.len() as u64 > PAGE;
            found.truncate(PAGE as usize);
            (found, more, false)
        }
    };
    Ok((hydrate(uow, found).await?, more_after, more_before))
}

